using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
namespace CampaignDemo.Editor {
 [InitializeOnLoad] public static class MergedArrowVerification {
  static double start;static int stage;static readonly List<string> checks=new List<string>();static BattleUnit a,b;static MergedMovementArrows display;static float phase;
  static MergedArrowVerification(){if(SessionState.GetBool("VerifyMergedArrows",false)){start=EditorApplication.timeSinceStartup;checks.AddRange(SessionState.GetString("MergedGeometryChecks","").Split(new[]{'\n'},StringSplitOptions.RemoveEmptyEntries));EditorApplication.update+=Poll;Application.logMessageReceived+=Log;}}
  static void Check(bool yes,string message){if(!yes)throw new Exception(message);checks.Add("PASS "+message);}
  static MovementArrowGeometry.Input Arrow(string id,Vector2 start,Vector2 end,float radius=.7f){return new MovementArrowGeometry.Input{id=id,owner="A",start=start,direction=Vector2.right,radius=radius,route=new List<Vector2>{start,start+Vector2.right*3,end}};}
  public static void Run(){
   File.WriteAllText("merged-arrow-errors.txt","");
   var one=Arrow("a",Vector2.zero,new Vector2(9,2));var two=Arrow("b",new Vector2(0,-1),new Vector2(9,-3));
   Check(Mathf.Abs(MovementArrowGeometry.Radius(.5f,3)/MovementArrowGeometry.Radius(.5f,2)-1.2f)<.0001f,"each echelon adds twenty percent to radius");
   Check(Vector2.Dot(MovementArrowGeometry.Perpendicular(new Vector2(3,4)),new Vector2(3,4))<.0001f,"root half widths are perpendicular to velocity");
   Check(MovementArrowGeometry.Groups(new[]{one,two}).Count==1,"overlapping radius circles merge");two.start=new Vector2(0,-3);Check(MovementArrowGeometry.Groups(new[]{one,two}).Count==2,"separated moving arrows split");two.start=new Vector2(0,-1);two.owner="B";Check(MovementArrowGeometry.Groups(new[]{one,two}).Count==2,"different factions never merge");two.owner="A";
   var inputs=new[]{one,two};MovementArrowGeometry.SharedOrigin(inputs,new[]{0,1},out var origin,out var direction,out var radius);Check(Mathf.Abs(origin.y+.5f)<.0001f&&radius>.7f,"common origin spans both unit footprints");
   var first=MovementArrowGeometry.Build(one,origin,direction,radius,true);var second=MovementArrowGeometry.Build(two,origin,direction,radius,true);Check(first.tip==one.route.Last()&&second.tip==two.route.Last(),"different destinations are retained exactly");Check(Vector2.Distance(first.polygon[0],second.polygon[0])<.0001f,"merged branches share identical open root");
   var single=MovementArrowGeometry.UnionOutline(new[]{first});Check(!single.Any(e=>Vector2.Distance(e.a,first.polygon.Last())<.0001f&&Vector2.Distance(e.b,first.polygon[0])<.0001f),"tail closure edge is excluded");
   var duplicates=MovementArrowGeometry.UnionOutline(new[]{first,first});Check(duplicates.Count==single.Count,"duplicate contours collapse to one outline");
   var union=MovementArrowGeometry.UnionOutline(new[]{first,second});Check(union.Count<single.Count+MovementArrowGeometry.UnionOutline(new[]{second}).Count,"overlapping interior contours are removed");var chains=MovementArrowGeometry.Chains(union);Check(chains.Count<=3,"union outline stitches into continuous open contours: "+chains.Count);
   var branch1=first.polygon[0]-origin;var neck=first.wingLeft-first.tip;Check(branch1.magnitude>neck.magnitude,"arrow tapers from broad origin to narrow endpoint");
   EditorSceneManager.OpenScene("Assets/Scenes/TacticalSandbox.unity");var world=UnityEngine.Object.FindObjectOfType<BattleWorld>();var visual=world.GetComponent<MergedMovementArrows>();if(visual==null)visual=world.gameObject.AddComponent<MergedMovementArrows>();visual.world=world;visual.color=new Color(.08f,.35f,.70f,1);visual.showDetectionCircles=false;EditorSceneManager.MarkSceneDirty(world.gameObject.scene);EditorSceneManager.SaveScene(world.gameObject.scene);
   SessionState.SetString("MergedGeometryChecks",string.Join("\n",checks));SessionState.SetBool("VerifyMergedArrows",true);start=EditorApplication.timeSinceStartup;EditorApplication.update+=Poll;Application.logMessageReceived+=Log;EditorApplication.EnterPlaymode();
  }
  static void Log(string text,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception)File.AppendAllText("merged-arrow-errors.txt",text+"\n"+stack+"\n");}
  static void Move(BattleUnit u,Vector3 start,Vector3 target){u.transform.position=start;u.SetWorking(false);var march=u.GetComponent<LocalMarchOrder>();if(march==null)march=u.gameObject.AddComponent<LocalMarchOrder>();march.style=LocalMarchStyle.Forced;march.world=u.Campaign.world;u.Motor.Commit(new[]{new RoadPoint(start.x,start.y),new RoadPoint(start.x+3,start.y),new RoadPoint(target.x,target.y)},()=>.015f);}
  static void Poll(){try{
   if(EditorApplication.timeSinceStartup-start>120)throw new Exception("runtime timed out");if(!EditorApplication.isPlaying||Time.time<1)return;var world=UnityEngine.Object.FindObjectOfType<BattleWorld>();if(world==null||!world.Initialized)return;display=world.GetComponent<MergedMovementArrows>();
   if(stage==0){foreach(var ai in UnityEngine.Object.FindObjectsOfType<MonoBehaviour>())if(ai.GetType().Name.StartsWith("AI"))ai.enabled=false;foreach(var u in world.units)u.Motor.Stop();a=world.units.First(u=>u.ownerId=="A"&&u.combatDefinition.role==UnitRole.Infantry);b=world.units.First(u=>u.ownerId=="A"&&u!=a&&u.combatDefinition.role==UnitRole.Infantry);world.fogEnabled=false;Move(a,new Vector3(-7,1),new Vector3(3,2));display.Refresh();Check(display.MovingCount==1&&display.GroupCount==1,"single active order renders new arrow system");Check(MergedMovementArrows.Owns(a.Motor),"legacy arrow renderer is replaced");Check(!display.showDetectionCircles,"detection circles hidden by default");stage=1;phase=Time.time;return;}
   if(stage==1&&Time.time-phase>.3f){Move(b,new Vector3(-7,.1f),new Vector3(3,-3));display.Refresh();Check(display.MovingCount==2&&display.MergedGroupCount==1,"later-issued movement joins already-moving arrow");Check(display.Inputs.Count==2&&display.Inputs[0].route.Last()!=display.Inputs[1].route.Last(),"both distinct live destinations remain available");Check(!display.GetComponentsInChildren<MeshFilter>().Any(m=>m.name=="空心合并箭头轮廓"),"no filled arrow mesh exists");var lines=display.GetComponentsInChildren<LineRenderer>().Where(l=>l.enabled&&l.name=="空心合并箭头轮廓").ToArray();Check(lines.Length>0&&lines.All(l=>!l.loop&&l.startColor.b>l.startColor.r),"visible arrows are blue open polylines");b.transform.position=new Vector3(-7,-3);display.Refresh();Check(display.MergedGroupCount==1,"fixed-arrow detection persists while units move apart");Move(b,new Vector3(-7,-4),new Vector3(3,-5));display.Refresh();Check(display.GroupCount==2&&display.MergedGroupCount==0,"new distant order splits fixed-arrow groups");Move(b,new Vector3(-7,.1f),new Vector3(3,-3));display.Refresh();Check(display.MergedGroupCount==1,"new nearby order merges with persistent arrows");b.Motor.Stop();display.Refresh();Check(display.MovingCount==1&&display.MergedGroupCount==0,"stopped unit is removed from merge group");Move(b,new Vector3(-7,.1f),new Vector3(3,-3));stage=2;phase=Time.time;return;}
   if(stage==2&&Time.time-phase>.15f){display.Refresh();var oldRoutes=a.Motor.GetType().GetField("view",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(a.Motor) as RoadRouteView;Check(oldRoutes.GetComponent<LineRenderer>().positionCount==0,"old committed arrow has no remaining geometry");world.setup.mapCamera.transform.position=new Vector3(-1,0,-10);world.setup.mapCamera.orthographicSize=6;if(SessionState.GetBool("WhiteMapOverview",false)){world.setup.mapCamera.transform.position=new Vector3(1.8f,0,-10);world.setup.mapCamera.orthographicSize=10;SessionState.SetBool("WhiteMapOverview",false);}Capture(world.setup.mapCamera);File.WriteAllText("merged-arrow-verification.txt",string.Join("\n",checks));SessionState.SetBool("VerifyMergedArrows",false);EditorApplication.update-=Poll;EditorApplication.Exit(0);}
  }catch(Exception e){File.WriteAllText("merged-arrow-verification.txt",e+"\n"+string.Join("\n",checks));SessionState.SetBool("VerifyMergedArrows",false);EditorApplication.update-=Poll;Debug.LogException(e);EditorApplication.Exit(1);}}
  static void Capture(Camera c){var rt=new RenderTexture(1600,900,24);c.targetTexture=rt;foreach(var canvas in UnityEngine.Object.FindObjectsOfType<Canvas>()){canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=c;canvas.planeDistance=1;canvas.overrideSorting=true;canvas.sortingOrder=1000;}Canvas.ForceUpdateCanvases();c.Render();RenderTexture.active=rt;var t=new Texture2D(1600,900,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1600,900),0,0);t.Apply();File.WriteAllBytes("merged-arrow-preview.png",t.EncodeToPNG());c.targetTexture=null;RenderTexture.active=null;UnityEngine.Object.Destroy(t);UnityEngine.Object.Destroy(rt);}
 }
}

